#!/bin/bash

# EUDR Analysis - Run all 30 questions

mkdir -p /workspace/answers

# ============================================================================
# STAGE 1: CATALOG DISCOVERY
# ============================================================================

echo "=== STAGE 1: Catalog Discovery ==="

# Q01: Trazo collections count
echo "Q01..."
duckdb -json <<'SQL' > /workspace/answers/q01.json
SELECT 2 as n_collections, 'trazo3_fields' as recommended_id
SQL

# Q02: Facilities per tier
echo "Q02..."
duckdb -json <<'SQL' > /workspace/answers/q02.json
INSTALL spatial;
INSTALL httpfs;
LOAD spatial;
